<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>The Great Wave off Kanagawa — low poly</title>
<style>
  html, body { margin: 0; height: 100%; background: #e7dcc2; overflow: hidden; }
  #c { display: block; width: 100vw; height: 100vh; }
  #cap {
    position: fixed; left: 14px; bottom: 12px; z-index: 2;
    font: 12px/1.4 system-ui, sans-serif; color: #4a4335;
    background: rgba(231,220,194,0.6); padding: 6px 10px; border-radius: 6px;
    letter-spacing: .3px; pointer-events: none;
  }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="cap">The Great Wave off Kanagawa · after Hokusai · low-poly rebuild</div>
<script type="module">
import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.170.0/build/three.module.js';

// ---- palette sampled from the print ----
const COL = {
  sky:      0xe7dcc2, deep: 0x163a5e, blue: 0x235a86, blueLt: 0x6fa3c4,
  foam:     0xf3efe3, foamSh: 0xcfe0e8, ink: 0x1d2430,
  boat:     0xcf9463, fuji: 0x2c3e56, fujiSnow: 0xeef1f3, water: 0x2a557e, skyHi: 0xf0e8d2,
};

const scene = new THREE.Scene();
scene.background = new THREE.Color(COL.sky);
scene.fog = new THREE.Fog(COL.sky, 34, 82);

const camera = new THREE.PerspectiveCamera(44, innerWidth/innerHeight, 0.1, 200);
camera.position.set(-3, 8, 31);
camera.lookAt(-3, 6, 0);

const renderer = new THREE.WebGLRenderer({ canvas: document.getElementById('c'), antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.setSize(innerWidth, innerHeight);

scene.add(new THREE.AmbientLight(0xfff4e0, 0.9));
const sun = new THREE.DirectionalLight(0xfff0d8, 1.1); sun.position.set(-8, 18, 12); scene.add(sun);
const fill = new THREE.DirectionalLight(0xbcd4e8, 0.35); fill.position.set(12, 6, -8); scene.add(fill);

const mat = (c, o={}) => new THREE.MeshStandardMaterial({ color: c, flatShading: true, roughness: 0.95, metalness: 0, ...o });
const M = { deep: mat(COL.deep), blue: mat(COL.blue), blueLt: mat(COL.blueLt), foam: mat(COL.foam),
  foamSh: mat(COL.foamSh), ink: mat(COL.ink), boat: mat(COL.boat), fuji: mat(COL.fuji),
  fujiSnow: mat(COL.fujiSnow), water: mat(COL.water) };

function smoothY(x, pts){
  if (x <= pts[0][0]) return pts[0][1];
  if (x >= pts[pts.length-1][0]) return pts[pts.length-1][1];
  for (let i=0;i<pts.length-1;i++){
    if (x>=pts[i][0] && x<=pts[i+1][0]){
      const p0=pts[Math.max(0,i-1)], p1=pts[i], p2=pts[i+1], p3=pts[Math.min(pts.length-1,i+2)];
      const t=(x-p1[0])/(p2[0]-p1[0]), t2=t*t, t3=t2*t;
      return 0.5*((2*p1[1])+(-p0[1]+p2[1])*t+(2*p0[1]-5*p1[1]+4*p2[1]-p3[1])*t2+(-p0[1]+3*p1[1]-3*p2[1]+p3[1])*t3);
    }
  }
  return 0;
}

// ---- water base ----
const waterGeo = new THREE.PlaneGeometry(95, 70, 26, 16);
waterGeo.rotateX(-Math.PI/2);
const water = new THREE.Mesh(waterGeo, M.water);
water.position.y = -0.4; scene.add(water);
const waterBase = waterGeo.attributes.position.array.slice();

// ---- big curling wave, anchored LEFT, crest curls over at top-left ----
const bigWave = new THREE.Group();
// wave face: tall on the left, sloping down to the right (the trough)
const WPTS = [[-26,8],[-20,12.5],[-15,13.5],[-10,10],[-5,5.5],[0,2.5],[4,1]];
function buildWall(pts, x0, x1, z0, z1, nx, nz, lean){
  const pos=[], idx=[];
  for (let i=0;i<=nx;i++){
    const x = x0 + (x1-x0)*i/nx;
    for (let j=0;j<=nz;j++){
      const z = z0 + (z1-z0)*j/nz;
      let y = smoothY(x, pts) + lean*(z-z0)/(z1-z0);
      y += 0.3*Math.sin(x*0.7 + z*0.6);
      pos.push(x, y, z);
    }
  }
  for (let i=0;i<nx;i++) for (let j=0;j<nz;j++){
    const a=i*(nz+1)+j, b=a+nz+1; idx.push(a,b,a+1, b,b+1,a+1);
  }
  const g=new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos,3));
  g.setIndex(idx); g.computeVertexNormals(); return g;
}
bigWave.add(new THREE.Mesh(buildWall(WPTS, -26, 4, -8, 8, 28, 8, 3.0), M.deep));

